'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var realf = require( '@stdlib/complex/float32/real' );
var imagf = require( '@stdlib/complex/float32/imag' );
var real = require( '@stdlib/complex/float64/real' );
var imag = require( '@stdlib/complex/float64/imag' );
var isComplexLike = require( '@stdlib/assert/is-complex-like' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var factory = require( './../lib' );


// FUNCTIONS //

/**
* Comparison function for complex128.
*
* @private
* @param {Complex128} a - first value
* @param {Complex128} b - second value
* @returns {number} comparison result
*/
function compareFcn128( a, b ) {
	var re1;
	var re2;
	var im1;
	var im2;
	re1 = real( a );
	re2 = real( b );
	if ( re1 < re2 ) {
		return -1;
	}
	if ( re1 > re2 ) {
		return 1;
	}
	im1 = imag( a );
	im2 = imag( b );
	if ( im1 < im2 ) {
		return -1;
	}
	if ( im1 > im2 ) {
		return 1;
	}
	return 0;
}

/**
* Comparison function for complex64.
*
* @private
* @param {Complex64} a - first value
* @param {Complex64} b - second value
* @returns {number} comparison result
*/
function compareFcn64( a, b ) {
	var re1;
	var re2;
	var im1;
	var im2;
	re1 = realf( a );
	re2 = realf( b );
	if ( re1 < re2 ) {
		return -1;
	}
	if ( re1 > re2 ) {
		return 1;
	}
	im1 = imagf( a );
	im2 = imagf( b );
	if ( im1 < im2 ) {
		return -1;
	}
	if ( im1 > im2 ) {
		return 1;
	}
	return 0;
}


// MAIN //

bench( format( '%s::complex128:toSorted', pkg ), function benchmark( b ) {
	var Complex128Array;
	var out;
	var arr;
	var i;

	Complex128Array = factory( 'complex128' );
	arr = new Complex128Array( [ 1, 2, 3, 4, 5, 6 ] );

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		out = arr.toSorted( compareFcn128 );
		if ( typeof out !== 'object' ) {
			b.fail( 'should return an object' );
		}
	}
	b.toc();
	if ( !isComplexLike( out.get( 0 ) ) ) {
		b.fail( 'should return a complex array' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '%s::complex64:toSorted', pkg ), function benchmark( b ) {
	var Complex64Array;
	var out;
	var arr;
	var i;

	Complex64Array = factory( 'complex64' );
	arr = new Complex64Array( [ 1, 2, 3, 4, 5, 6 ] );

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		out = arr.toSorted( compareFcn64 );
		if ( typeof out !== 'object' ) {
			b.fail( 'should return an object' );
		}
	}
	b.toc();
	if ( !isComplexLike( out.get( 0 ) ) ) {
		b.fail( 'should return a complex array' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});
